import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for DateTimeSerializerBase._asTimestamp
 */
public class DateTimeSerializerBase__asTimestamp_TriageGen0Test {

    /**
     * Concrete implementation of the abstract DateTimeSerializerBase for testing purposes.
     */
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<Date> {

        protected TestDateTimeSerializer(Class<Date> type, Boolean useTimestamp, java.text.DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
        }

        @Override
        public void serialize(Date value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) throws java.io.IOException {
            // Not needed for _asTimestamp tests
        }

        @Override
        protected long _timestamp(Date value) {
            return value.getTime();
        }

        @Override
        public com.fasterxml.jackson.databind.JsonSerializer<?> createContextual(SerializerProvider serializers, com.fasterxml.jackson.databind.ser.BeanProperty property) {
            return this;
        }

        @Override
        public com.fasterxml.jackson.databind.JsonNode getSchema(SerializerProvider serializers, com.fasterxml.jackson.databind.JavaType typeHint) {
            return null;
        }

        @Override
        public void acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint) {
            // Not needed
        }

        @Override
        protected void _acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint, boolean asNumber) {
            // Not needed
        }
    }

    @Test
    public void testAsTimestamp_WhenUseTimestampIsNotNull_ReturnsUseTimestampValue() {
        // Case 1: _useTimestamp is true
        TestDateTimeSerializer serializerTrue = new TestDateTimeSerializer(Date.class, true, null);
        assertTrue(serializerTrue._asTimestamp(null));

        // Case 2: _useTimestamp is false
        TestDateTimeSerializer serializerFalse = new TestDateTimeSerializer(Date.class, false, null);
        assertFalse(serializerFalse._asTimestamp(null));
    }

    @Test
    public void testAsTimestamp_WhenUseTimestampIsNullAndCustomFormatIsNull_ReturnsSerializerFeature() {
        SerializerProvider serializers = mock(SerializerProvider.class);
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, null);

        // Case 3: Feature is enabled
        when(serializers.isEnabled(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)).thenReturn(true);
        assertTrue(serializer._asTimestamp(serializers));

        // Case 4: Feature is disabled
        when(serializers.isEnabled(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)).thenReturn(false);
        assertFalse(serializer._asTimestamp(serializers));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAsTimestamp_WhenUseTimestampIsNull_CustomFormatIsNull_SerializersIsNull_ThrowsException() {
        // Case 5: Throws NPE/IllegalArgumentException when serializers is null and no custom format
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, null);
        serializer._asTimestamp(null);
    }

    @Test
    public void testAsTimestamp_WhenCustomFormatIsNotNull_ReturnsFalse() {
        // Case 6: _customFormat is not null, should return false regardless of serializers
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, sdf);

        // Even if serializers says true, custom format presence forces false
        SerializerProvider serializers = mock(SerializerProvider.class);
        when(serializers.isEnabled(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)).thenReturn(true);

        assertFalse(serializer._asTimestamp(serializers));
    }

    @Test
    public void testAsTimestamp_WithWithFormat() {
        // Testing the provided helper method withFormat to ensure state transitions
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, null);

        // Check transition to useTimestamp = true
        TestDateTimeSerializer serializerWithTimestamp = (TestDateTimeSerializer) serializer.withFormat(true, null);
        assertTrue(serializerWithTimestamp._asTimestamp(null));

        // Check transition to customFormat set
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        TestDateTimeSerializer serializerWithFormat = (TestDateTimeSerializer) serializer.withFormat(null, sdf);
        assertFalse(serializerWithFormat._asTimestamp(null));
    }
}
